// b11o2 is the order-2 part of block phhhhh,phhhhh, <a,i,j,k,l,m|M|b,n,o,i1,j1,k1>.
func (el *Elem) b11o2(a, i, j, k, l, m, b, n, o, i1, j1, k1 int) float64 {
	var v float64
	// (1)
	v += el.b11o2g0(a, i, j, k, l, m, b, n, o, i1, j1, k1)
	return v
}

// B11 is block phhhhh,phhhhh of the secular matrix,
// <a,i,j,k,l,m|M|b,n,o,i1,j1,k1>, summed over the orders the scheme keeps.
func (el *Elem) B11(a, i, j, k, l, m, b, n, o, i1, j1, k1 int) float64 {
	var v float64
	if el.maxOrder[2] >= 0 {
		v += el.b11o0(a, i, j, k, l, m, b, n, o, i1, j1, k1)
	}
	if el.maxOrder[2] >= 1 {
		v += el.b11o1(a, i, j, k, l, m, b, n, o, i1, j1, k1)
	}
	if el.maxOrder[2] >= 2 {
		v += el.b11o2(a, i, j, k, l, m, b, n, o, i1, j1, k1)
	}
	return v
}
